import { Kolam, makeGrid, generateSikku, symmetricStrokes } from './engine.js';

/**
 * Pattern library. Honesty rules:
 *  - "Traditional form": the STRUCTURE (dot arrangement + drawing rule) is the documented
 *    traditional one; the specific line route is generated by the mirror-curve method.
 *  - "Original design": drawn for this project in the style of the category.
 * We never claim a generated pattern is a specific named heirloom design.
 */

