const loopsBetween = (n) => (n <= 1 ? 'a single unbroken line' : `${n} interlaced loops`);

/** build a mirror-curve preset deterministically (cached) */
function sikku({ size, shape, sym, seed, target = 1, density = 0.3 }) {
  const grid = makeGrid(size, shape);
  const { mirrors, count } = generateSikku(grid, { sym, seed, target, density });
  return { size, shape, mirrors: [...mirrors], count };
}

// ---- hand-authored curves (grid units) for pulli / padi / pongal designs --------
function petal(cx, cy, r, a, w = 0.45) {
  const tip = [cx + Math.cos(a) * r, cy + Math.sin(a) * r];
  const l = [cx + Math.cos(a - w) * r * 0.55, cy + Math.sin(a - w) * r * 0.55];
  const rr = [cx + Math.cos(a + w) * r * 0.55, cy + Math.sin(a + w) * r * 0.55];
  return [[cx, cy], l, tip, rr, [cx, cy]];
}
function circlePts(cx, cy, r, n = 28, a0 = 0) { const o = []; for (let i = 0; i <= n; i++) { const a = a0 + (i / n) * Math.PI * 2; o.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]); } return o; }

function lotus(size) {
  const c = size / 2, g = makeGrid(size);
  const strokes = [];
  for (const s of symmetricStrokes(petal(c, c, size * 0.36, -Math.PI / 2, 0.42), g, 'r8')) strokes.push({ type: 'free', pts: s });
  for (const s of symmetricStrokes(petal(c, c, size * 0.22, -Math.PI / 2 + Math.PI / 8, 0.5), g, 'r8')) strokes.push({ type: 'free', pts: s });
  strokes.push({ type: 'free', pts: circlePts(c, c, 0.32, 20) });
  strokes.push({ type: 'free', pts: circlePts(c, c, size * 0.44, 48) });
  return strokes;
}

function starOfLines(size) {
  // pulli style: straight lines joining dots into an eight-pointed star of squares
  const strokes = []; const n = size - 1, o = 0.5;
  const sq = [[o, o], [o + n, o], [o + n, o + n], [o, o + n], [o, o]];
  const c = size / 2, R = n / Math.SQRT2;
  const diamond = [[c, c - R * 0.98], [c + R * 0.98, c], [c, c + R * 0.98], [c - R * 0.98, c], [c, c - R * 0.98]].map(([x, y]) => [Math.max(o, Math.min(o + n, x)), Math.max(o, Math.min(o + n, y))]);
  strokes.push({ type: 'line', pts: sq }, { type: 'line', pts: diamond });
  // inner square joining mid-dots
  const m = Math.floor(n / 4);
  strokes.push({ type: 'line', pts: [[o + m, o + m], [o + n - m, o + m], [o + n - m, o + n - m], [o + m, o + n - m], [o + m, o + m]] });
  strokes.push({ type: 'line', pts: [[o, o], [o + n, o + n]] }, { type: 'line', pts: [[o + n, o], [o, o + n]] });
  return strokes;
}

function padiSteps(size) {
  // padi: double-line "steps" forming a stepped cross with a square frame
  const strokes = []; const c = size / 2;
  const frame = (d) => [[c - d, c - d], [c + d, c - d], [c + d, c + d], [c - d, c + d], [c - d, c - d]];
  strokes.push({ type: 'line', pts: frame(size * 0.46) }, { type: 'line', pts: frame(size * 0.42) });
  const k = size * 0.08;
  const arm = [];
  for (let s = 0; s < 4; s++) { arm.push([c - k * (1 + s), c - size * 0.38 + s * k]); arm.push([c - k * (2 + s), c - size * 0.38 + s * k]); }
  const half = [[c - k, c - size * 0.38], ...arm];
  for (const pts of symmetricStrokes(half, makeGrid(size), 'r4')) strokes.push({ type: 'line', pts });
  for (const pts of symmetricStrokes(half.map(([x, y]) => [2 * c - x, y]), makeGrid(size), 'r4')) strokes.push({ type: 'line', pts });
  strokes.push({ type: 'line', pts: frame(size * 0.1) });
  strokes.push({ type: 'line', pts: [[c - size * 0.1, c], [c - size * 0.38, c]] }, { type: 'line', pts: [[c + size * 0.1, c], [c + size * 0.38, c]] }, { type: 'line', pts: [[c, c - size * 0.1], [c, c - size * 0.38]] }, { type: 'line', pts: [[c, c + size * 0.1], [c, c + size * 0.38]] });
  return strokes;
}

function pongalPot(size) {
  const c = size / 2, s = size / 9;
  const S = (pts) => pts.map(([x, y]) => [c + x * s, c + y * s]);
  const strokes = [];
  // pot body
  strokes.push({ type: 'free', pts: S([[-1.2, -0.6], [-2.4, 0.4], [-2.2, 1.9], [-1, 2.7], [1, 2.7], [2.2, 1.9], [2.4, 0.4], [1.2, -0.6]]), color: '#f2b630' });
  strokes.push({ type: 'line', pts: S([[-1.4, -0.6], [1.4, -0.6]]), color: '#f2b630' });
  strokes.push({ type: 'free', pts: S([[-2.1, 1.2], [-1, 1.5], [0, 1.2], [1, 1.5], [2.1, 1.2]]), color: '#e2572c' });
  // overflowing pongal — the auspicious boil-over
  strokes.push({ type: 'free', pts: S([[-1.3, -0.65], [-1.2, -1.4], [-0.6, -1.7], [0, -1.35], [0.6, -1.8], [1.2, -1.4], [1.3, -0.65]]), color: '#fbf3df' });
  // sugarcane on both sides
  for (const sx of [-1, 1]) {
    strokes.push({ type: 'line', pts: S([[sx * 3.2, 3.2], [sx * 2.4, -3.4]]), color: '#2f8f5b' });
    strokes.push({ type: 'free', pts: S([[sx * 2.45, -3.0], [sx * 1.6, -3.9], [sx * 1.2, -3.6]]), color: '#2f8f5b' });
    strokes.push({ type: 'free', pts: S([[sx * 2.5, -2.4], [sx * 3.4, -3.3], [sx * 3.7, -2.9]]), color: '#2f8f5b' });
  }
  // the sun (Surya) above — Pongal thanks the sun for the harvest
  strokes.push({ type: 'free', pts: circlePts(c, c - 3.2 * s * 0.0 - s * 3.4, s * 0.55, 20), color: '#e2572c' });
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; strokes.push({ type: 'line', pts: [[c + Math.cos(a) * s * 0.8, c - s * 3.4 + Math.sin(a) * s * 0.8], [c + Math.cos(a) * s * 1.2, c - s * 3.4 + Math.sin(a) * s * 1.2]], color: '#e2572c' }); }
  return strokes;
}

function trackKolam(size) {
  // contemporary: two parallel "rails" bending around dots with sleepers — a nod to Central
  const strokes = []; const c = size / 2;
  for (const off of [-0.18, 0.18]) {
    const pts = []; for (let i = 0; i <= 60; i++) { const t = i / 60; const x = 0.5 + t * (size - 1); pts.push([x, c + Math.sin(t * Math.PI * 2) * size * 0.25 + off]); }
    strokes.push({ type: 'free', pts });
  }
  for (let i = 0; i <= 14; i++) { const t = i / 14, x = 0.5 + t * (size - 1), y = c + Math.sin(t * Math.PI * 2) * size * 0.25; const dy = Math.cos(t * Math.PI * 2) * size * 0.25 * Math.PI * 2 / (size - 1); const L = Math.hypot(1, dy); strokes.push({ type: 'line', pts: [[x - (-dy / L) * 0.35, y - (1 / L) * 0.35], [x + (-dy / L) * 0.35, y + (1 / L) * 0.35]] }); }
  return strokes;
}

