const cache = new Map();
export const PRESETS = RAW.map((p) => ({ ...p, get data() { if (!cache.has(p.id)) cache.set(p.id, p.build()); return cache.get(p.id); } }));

export function presetKolam(id, overrideStyle = {}) {
  const p = PRESETS.find((x) => x.id === id) || PRESETS[0];
  const d = p.data;
  const pal = PALETTES.find((x) => x.id === p.palette) || PALETTES[0];
  const k = new Kolam({ size: d.size, shape: d.shape, mirrors: d.mirrors || [], strokes: d.strokes ? JSON.parse(JSON.stringify(d.strokes)) : [],
    style: { line: pal.line, bg: pal.bg, multicolor: !!pal.multicolor, colors: pal.colors || null, ...(d.style || {}), ...overrideStyle } });
  k.sikkuOn = d.sikkuOn !== false;
  k.meta = { preset: p.id, name: p.name, loops: d.count != null ? loopsBetween(d.count) : null };
  return k;
}
